-- table: payment_types
CREATE TABLE payment_types (payment_type_id INTEGER PRIMARY KEY, description TEXT NOT NULL);

-- table: rate_codes
CREATE TABLE rate_codes (rate_code_id INTEGER PRIMARY KEY, description TEXT NOT NULL);

-- table: taxi_zones
CREATE TABLE taxi_zones (
    location_id  INTEGER PRIMARY KEY,
    borough      TEXT NOT NULL,
    zone         TEXT NOT NULL,
    service_zone TEXT
);

-- table: trips
CREATE TABLE trips (
    trip_id               INTEGER PRIMARY KEY AUTOINCREMENT,
    vendor_id             INTEGER,
    pickup_datetime       TEXT    NOT NULL,
    dropoff_datetime      TEXT    NOT NULL,
    passenger_count       INTEGER,
    trip_distance         REAL    NOT NULL,
    pu_location_id        INTEGER REFERENCES taxi_zones(location_id),
    do_location_id        INTEGER REFERENCES taxi_zones(location_id),
    rate_code_id          INTEGER REFERENCES rate_codes(rate_code_id),
    payment_type          INTEGER REFERENCES payment_types(payment_type_id),
    fare_amount           REAL    NOT NULL,
    extra                 REAL    DEFAULT 0,
    mta_tax               REAL    DEFAULT 0,
    tip_amount            REAL    DEFAULT 0,
    tolls_amount          REAL    DEFAULT 0,
    improvement_surcharge REAL    DEFAULT 0,
    total_amount          REAL    NOT NULL,
    congestion_surcharge  REAL    DEFAULT 0,
    airport_fee           REAL    DEFAULT 0,
    trip_duration_min     REAL,
    speed_mph             REAL,
    fare_per_mile         REAL,
    tip_percentage        REAL,
    hour                  INTEGER,
    day_name              TEXT,
    pickup_date           TEXT,
    is_airport            INTEGER DEFAULT 0,
    pu_borough            TEXT,
    do_borough            TEXT,
    pu_zone               TEXT,
    do_zone               TEXT
);

-- index: idx_airport
CREATE INDEX idx_airport ON trips(is_airport);

-- index: idx_borough
CREATE INDEX idx_borough ON trips(pu_borough);

-- index: idx_date
CREATE INDEX idx_date    ON trips(pickup_date);

-- index: idx_fare
CREATE INDEX idx_fare    ON trips(fare_amount);

-- index: idx_hour
CREATE INDEX idx_hour    ON trips(hour);

-- index: idx_payment
CREATE INDEX idx_payment ON trips(payment_type);

-- index: idx_rate
CREATE INDEX idx_rate    ON trips(rate_code_id);

-- index: idx_zone
CREATE INDEX idx_zone    ON trips(pu_zone);

